var HONGHIN_WORDS = {
  H001: ["สมัยก่อนพุ้น ตี้เมืองปาราณสี มีพระญาจื่อพระเจ้าปุรันตปะ", "สมัยก่อนพุ้น ตี้เมืองปาราณสี มีพระญาจื่อพระเจ้าปุรันตปะ", "Long ago, in the city of Varanasi, there lived a king called Purantapa."],
  H002: ["ต๋อนเปิ้นอายุซาวปี๋ ยักษ์ผีดิบออกมาลุ๊กดงป่าไม้ต๋อนกลางคืน", "ต๋อนเปิ้นอายุซาวปี๋ ยักษ์ผีดิบออกมาลุ๊กดงป่าไม้ต๋อนกลางคืน", "When he was twenty, ghouls came out of the forest by night."],
  H003: ["หมู่มันลักเอาแม่ของพระญาไป เข้าไปในดงป่าไม้เลิ๊ก", "หมู่มันลักเอาแม่ของพระญาไป เข้าไปในดงป่าไม้เลิ๊ก", "They stole the king's own mother and took her away into the deep forest."],
  H004: ["บ่ามีไผโตยไปได้ ละก่อบ่ามีไผหันเปิ้นแห๋มเลย", "บ่ามีไผโตยไปได้ ละก่อบ่ามีไผหันเปิ้นแห๋มเลย", "No one could follow them, and no one ever found her."],
  H005: ["นี่เป๋นเรื่องของหงส์หิน", "นี่เป๋นเรื่องของหงส์หิน", "This is the story of Hong Hin, the swan of stone."],
  H006: ["พระญาใหญ่ขึ้นมา มีเมียหลวงจื่อนางวิมาลา ละก่อมีเมียน้อยแห๋มหกนาง", "พระญาใหญ่ขึ้นมา มีเมียหลวงจื่อนางวิมาลา ละก่อมีเมียน้อยแห๋มหกนาง", "The king grew up and married. His chief queen was Vimala, and he had six other wives."],
  H007: ["เมียน้อยตึงหกนาง มีลูกจายคนละคน", "เมียน้อยตึงหกนาง มีลูกจายคนละคน", "Each of the six had borne him a son."],
  H008: ["นางวิมาลามีต๊อง เกิ๋นสิบเดือนแล้ว ลูกก่อยังบ่าออกมา", "นางวิมาลามีต๊อง เกิ๋นสิบเดือนแล้ว ลูกก่อยังบ่าออกมา", "Vimala was with child, and the child would not come, even past the tenth month."],
  H009: ["หมอโหรผ่อดาวแล้วบอกว่า บ่าแม่นยักษ์มาร แต่เป๋นต๋นบุญ จะได้เป๋นพระญาครองเมือง", "หมอโหรผ่อดาวแล้วบอกว่า บ่าแม่นยักษ์มาร แต่เป๋นต๋นบุญ จะได้เป๋นพระญาครองเมือง", "The astrologers read the stars and said: this is no demon. It is a child of great merit, who will rule the land."],
  H010: ["เมียน้อยตึงหกได้ยินก่อกั๋วขนาด กั๋วลูกของตั๋วจะบ่าได้เป๋นอะหยั๋ง", "เมียน้อยตึงหกได้ยินก่อกั๋วขนาด กั๋วลูกของตั๋วจะบ่าได้เป๋นอะหยั๋ง", "The six wives heard it, and they were afraid. Their own sons would be nothing."],
  H011: ["เมื่อถึงเวลาออกลูก เมียน้อยตึงหกเข้าไปในห้อง ละก่อกั้นคนอื่นไว้ตางนอก", "เมื่อถึงเวลาออกลูก เมียน้อยตึงหกเข้าไปในห้อง ละก่อกั้นคนอื่นไว้ตางนอก", "When her time came, the six wives crowded into her room and kept everyone else away."],
  H012: ["นางวิมาลาเจ็บขนาด จ๋นสลบไป", "นางวิมาลาเจ็บขนาด จ๋นสลบไป", "Vimala fainted with the pain."],
  H013: ["หมู่นางเอาลูกหมาลายตั๋วหน้อยมาทาเลือด แล้ววางไว้ข้างนางวิมาลา", "หมู่นางเอาลูกหมาลายตั๋วหน้อยมาทาเลือด แล้ววางไว้ข้างนางวิมาลา", "They took a little spotted puppy, smeared it with her blood, and laid it beside her."],
  H014: ["ส่วนลูกจายแต้แต้ หมู่นางยู้ลงไปตางฮูใต้พื้น", "ส่วนลูกจายแต้แต้ หมู่นางยู้ลงไปตางฮูใต้พื้น", "And the baby boy they pushed down through a hole in the floor."],
  H015: ["บนสวรรค์ แท่นหินของพระอินทร์ฮ้อนขึ้นมา เปิ้นผ่อลงมา หันละอ่อนกำลังต๊กลงไป", "บนสวรรค์ แท่นหินของพระอินทร์ฮ้อนขึ้นมา เปิ้นผ่อลงมา หันละอ่อนกำลังต๊กลงไป", "Far above, Indra's stone throne grew hot. He looked down and saw the child falling."],
  H016: ["พระอินทร์กับวิสุกัมฮับละอ่อนไว้ก๋างอากาศ แล้วปาขึ้นไปบนสวรรค์", "พระอินทร์กับวิสุกัมฮับละอ่อนไว้ก๋างอากาศ แล้วปาขึ้นไปบนสวรรค์", "With Witsanukam he caught the baby in the air, and carried him up to heaven."],
  H017: ["เมียน้อยตึงหกไปบอกพระญาว่า เมียหลวงออกลูกเป๋นหมา นางไปคบกับหมา", "เมียน้อยตึงหกไปบอกพระญาว่า เมียหลวงออกลูกเป๋นหมา นางไปคบกับหมา", "The six told the king: your queen has borne a dog. She has been with dogs."],
  H018: ["พระญาเจื้อหมู่นาง วันนั้นเลยไล่นางวิมาลาออกจากเมือง", "พระญาเจื้อหมู่นาง วันนั้นเลยไล่นางวิมาลาออกจากเมือง", "The king believed them. That same day he drove Vimala out of the city."],
  H019: ["นางเตียวออกไปในความมืด ไห้ไปตวย กอดลูกหมาไว้ในแขน", "นางเตียวออกไปในความมืด ไห้ไปตวย กอดลูกหมาไว้ในแขน", "She walked into the night, weeping, the little dog in her arms."],
  H020: ["ตี้สวนปายเวียง มีป้ออุ้ยแม่อุ้ยสองคน บ่ามีลูกสักคน", "ตี้สวนปายเวียง มีป้ออุ้ยแม่อุ้ยสองคน บ่ามีลูกสักคน", "At an orchard on the edge of the city lived an old man and an old woman, who had no children."],
  H021: ["ป้ออุ้ยแม่อุ้ยจุดไต้ หันนางไห้อยู่ ก่อฮับนางไว้", "ป้ออุ้ยแม่อุ้ยจุดไต้ หันนางไห้อยู่ ก่อฮับนางไว้", "They lit a torch, saw the weeping lady, and took her in."],
  H022: ["ปั๋นของตี้มีหน้อยหน้อยหื้อ เผือก กล้วย ผักในสวน", "ปั๋นของตี้มีหน้อยหน้อยหื้อ เผือก กล้วย ผักในสวน", "They shared what little they had: taro, bananas, vegetables from the garden."],
  H023: ["นางเลยอยู่กับป้ออุ้ยแม่อุ้ย เหมือนเป๋นลูกสาว จ่วยยะสวน", "นางเลยอยู่กับป้ออุ้ยแม่อุ้ย เหมือนเป๋นลูกสาว จ่วยยะสวน", "And the queen lived on as their daughter, a gardener."],
  H024: ["บนสวรรค์ เมียของพระอินทร์จะหื้อนม แต่บ่ามีน้ำนม ละอ่อนเลยไห้", "บนสวรรค์ เมียของพระอินทร์จะหื้อนม แต่บ่ามีน้ำนม ละอ่อนเลยไห้", "In heaven, Indra's queens tried to nurse the child, but they had no milk, and he cried."],
  H025: ["ละอ่อนใหญ่ขึ้นมา แล้วถามว่า แม่ของข้าเป๋นไผ", "ละอ่อนใหญ่ขึ้นมา แล้วถามว่า แม่ของข้าเป๋นไผ", "He grew, and asked: who is my mother?"],
  H026: ["พระอินทร์เล่าหื้อฟังกู๊อย่าง เรื่องเมียน้อยตึงหก ลูกหมา ละก่อแม่ของเปิ้นตี้อยู่ในสวน", "พระอินทร์เล่าหื้อฟังกู๊อย่าง เรื่องเมียน้อยตึงหก ลูกหมา ละก่อแม่ของเปิ้นตี้อยู่ในสวน", "Indra told him everything: the six wives, the puppy, and his mother in the orchard."],
  H027: ["เมื่อละอ่อนอายุสิบสามปี๋ พระอินทร์ก่อเตียมหื้อเปิ้นปิ๊กเฮือน", "เมื่อละอ่อนอายุสิบสามปี๋ พระอินทร์ก่อเตียมหื้อเปิ้นปิ๊กเฮือน", "When the boy was thirteen, Indra made him ready to go home."],
  H028: ["เปิ้นเอาก้อนหินคำมา ว่าคาถาใส่ แล้วหินก่อกลายเป๋นหงส์ตี้บินได้", "เปิ้นเอาก้อนหินคำมา ว่าคาถาใส่ แล้วหินก่อกลายเป๋นหงส์ตี้บินได้", "He took a golden boulder, spoke words over it, and the stone became a swan that could fly."],
  H029: ["หงส์หิน บินไวเหมือนดาวต๊ก ละอ่อนบังคับมันด้วยสายจู๋ง", "หงส์หิน บินไวเหมือนดาวต๊ก ละอ่อนบังคับมันด้วยสายจู๋ง", "Hong Hin, the stone swan. It flew like a shooting star, and the boy steered it by its reins."],
  H030: ["แล้วพระอินทร์หื้อดาบตี้บ่ามีอะหยั๋งหักได้ จื่อดาบกัญไจย", "แล้วพระอินทร์หื้อดาบตี้บ่ามีอะหยั๋งหักได้ จื่อดาบกัญไจย", "And Indra gave him a sword that nothing could break: Kanchai."],
  H031: ["เปิ้นซ่อนหงส์ไว้ในป่าไม้ หงส์ก่อหุบตั๋วลงเหมือนขอนไม้เก่า", "เปิ้นซ่อนหงส์ไว้ในป่าไม้ หงส์ก่อหุบตั๋วลงเหมือนขอนไม้เก่า", "He hid the swan in the thicket, where it folded itself up to look like an old log."],
  H032: ["ตี้ตูบ เปิ้นบอกว่า ข้าเป๋นลูกของแม่", "ตี้ตูบ เปิ้นบอกว่า ข้าเป๋นลูกของแม่", "At the hut he said: I am your son."],
  H033: ["นางบ่าเจื้อ ย้อนเขาบอกว่าลูกของนางเป๋นหมา", "นางบ่าเจื้อ ย้อนเขาบอกว่าลูกของนางเป๋นหมา", "She would not believe him. Her child, they had told her, was a dog."],
  H034: ["เปิ้นเลยอธิษฐานว่า ถ้าข้าเป๋นลูกของแม่แต้ ขอหื้อน้ำนมของแม่ไหลมาหาข้า", "เปิ้นเลยอธิษฐานว่า ถ้าข้าเป๋นลูกของแม่แต้ ขอหื้อน้ำนมของแม่ไหลมาหาข้า", "So he made a vow of truth: if I am her son, let her milk come to me."],
  H035: ["น้ำนมของนางไหลมาหาเปิ้น นางก่อฮู้ กอดลูกแล้วไห้", "น้ำนมของนางไหลมาหาเปิ้น นางก่อฮู้ กอดลูกแล้วไห้", "Her milk flowed to him, and she knew. She held him and wept."],
  H036: ["นางใส่จื่อหื้อเปิ้นว่า ทุตคตขัตติวงศ์ เจ้าจายตี้เกิ๊ดมาลุ๊กความตุ๊ก", "นางใส่จื่อหื้อเปิ้นว่า ทุตคตขัตติวงศ์ เจ้าจายตี้เกิ๊ดมาลุ๊กความตุ๊ก", "She named him Thukkhata, the prince born of suffering."],
  H037: ["ปี้น้องตึงหกเล่นหมากบ้ากั๋นก๋างถนน ด้วยหมากบ้าคำ", "ปี้น้องตึงหกเล่นหมากบ้ากั๋นก๋างถนน ด้วยหมากบ้าคำ", "The six brothers played saba in the street, with pieces of solid gold."],
  H038: ["ละอ่อนบ่ามีคำ แม่เก็บหมากนิมแดงลุ๊กป่ามาหื้อถุงหนึ่ง", "ละอ่อนบ่ามีคำ แม่เก็บหมากนิมแดงลุ๊กป่ามาหื้อถุงหนึ่ง", "The boy had no gold. His mother brought him a bag of red seeds from the forest."],
  H039: ["ปี้น้องหัวขวัน หมากนิมแดงจะสู้คำได้กา", "ปี้น้องหัวขวัน หมากนิมแดงจะสู้คำได้กา", "The brothers laughed: seeds, against gold?"],
  H040: ["เปิ้นว่า ถ้าข้าแป้ ข้าจะเป๋นขี้ข้า ถ้าหมู่ตั๋วแป้ คำเป๋นของข้า", "เปิ้นว่า ถ้าข้าแป้ ข้าจะเป๋นขี้ข้า ถ้าหมู่ตั๋วแป้ คำเป๋นของข้า", "If I lose, I will be your servant, he said. If you lose, the gold is mine."],
  H041: ["เปิ้นโยนแล้วโยนแห๋ม ชนะกู๊ลูก แล้วเอาคำปิ๊กไปหื้อแม่", "เปิ้นโยนแล้วโยนแห๋ม ชนะกู๊ลูก แล้วเอาคำปิ๊กไปหื้อแม่", "He threw, and threw, and won every piece, and carried the gold home to his mother."],
  H042: ["ตี้ประตู๋เมืองตางใต้ ใต้ต้นต๋าลหลวง มีย่ายักษ์เถ้าตนหนึ่งอยู่", "ตี้ประตู๋เมืองตางใต้ ใต้ต้นต๋าลหลวง มีย่ายักษ์เถ้าตนหนึ่งอยู่", "At the south gate, under a great sugar palm, lived an old giantess."],
  H043: ["กู๊เจ็ดวัน นางจับคนบนถนนกิ๋นดิบดิบ บ่ามีไผก้าอยู่ตางนั้นแห๋ม", "กู๊เจ็ดวัน นางจับคนบนถนนกิ๋นดิบดิบ บ่ามีไผก้าอยู่ตางนั้นแห๋ม", "Every seventh day she caught people on the road and ate them raw. No one lived on that side of the city any more."],
  H044: ["ละอ่อนเตียวซื่อไปตี้ต้นต๋าล ย่ายักษ์โดดเข้าใส่", "ละอ่อนเตียวซื่อไปตี้ต้นต๋าล ย่ายักษ์โดดเข้าใส่", "The boy walked straight to the tree. She sprang at him."],
  H045: ["เปิ้นว่า กึ๊ดว่าข้ากิ๋นง่ายกา ยังบ่าเกยขบพริกขี้หนูหนา", "เปิ้นว่า กึ๊ดว่าข้ากิ๋นง่ายกา ยังบ่าเกยขบพริกขี้หนูหนา", "You think I am easy meat? he said. You have never bitten a bird's-eye chilli."],
  H046: ["เปิ้นจักดาบกัญไจย ฟันเตื้อเดียว ย่ายักษ์ก่อต๋าย", "เปิ้นจักดาบกัญไจย ฟันเตื้อเดียว ย่ายักษ์ก่อต๋าย", "He drew Kanchai, and with one stroke the giantess was dead."],
  H047: ["แล้วปี้น้องตึงหกก่อมา ตี๋ซากยักษ์ เอาเลือดทาเสื้อผ้า แล้วจ่ายคำหื้อเปิ้นอยู่เงียบเงียบ", "แล้วปี้น้องตึงหกก่อมา ตี๋ซากยักษ์ เอาเลือดทาเสื้อผ้า แล้วจ่ายคำหื้อเปิ้นอยู่เงียบเงียบ", "Then the six brothers came, beat the body, smeared its blood on their clothes, and paid him to keep quiet."],
  H048: ["หมู่เขาไปบอกพระญาว่าฆ่ายักษ์ได้ พระญาสงสัย แต่ก่อจัดงานเลี้ยงหื้อ", "หมู่เขาไปบอกพระญาว่าฆ่ายักษ์ได้ พระญาสงสัย แต่ก่อจัดงานเลี้ยงหื้อ", "They told the king they had killed her. The king had his doubts, but he gave them a feast."],
  H049: ["พระญานึกถึงแม่ตี้ถูกลักไป เลยว่า ถ้าเก่งขนาด ไปเอาแม่ปิ๊กมา บ่าอั้นจะต้องต๋าย", "พระญานึกถึงแม่ตี้ถูกลักไป เลยว่า ถ้าเก่งขนาด ไปเอาแม่ปิ๊กมา บ่าอั้นจะต้องต๋าย", "The king remembered his stolen mother. If you are such heroes, he said, go and bring her back, or die."],
  H050: ["ปี้น้องกั๋วจ๋นสั่น ไปหาละอ่อนแห๋ม เอาคำไปโตย", "ปี้น้องกั๋วจ๋นสั่น ไปหาละอ่อนแห๋ม เอาคำไปโตย", "The brothers were terrified. Again they went to the boy, with more gold."],
  H051: ["หมู่เขายกตั๊พสามพันคนไปเถิงแม่น้ำหลวง แล้วก่อยั้ง บ่าก้าข้าม", "หมู่เขายกตั๊พสามพันคนไปเถิงแม่น้ำหลวง แล้วก่อยั้ง บ่าก้าข้าม", "They marched with three thousand men to a great river, and there they stopped, too frightened to cross."],
  H052: ["ละอ่อนขี่หงส์หินบินข้ามหัวหมู่เขา หายเข้าไปในเมฆ", "ละอ่อนขี่หงส์หินบินข้ามหัวหมู่เขา หายเข้าไปในเมฆ", "The boy rose on his stone swan over their heads and was gone into the clouds."],
  H053: ["เปิ้นมาเถิงเมืองของพญายักษ์วัสสะวโร แล้วลงบนหลังคาปราสาท", "เปิ้นมาเถิงเมืองของพญายักษ์วัสสะวโร แล้วลงบนหลังคาปราสาท", "He came to the city of the giant king Wassawaro, and landed on the palace roof."],
  H054: ["ตี้หั้นเปิ้นหันลูกสาวพญายักษ์ จื่อมุกขะวดี ตึงสองฮักกั๋นเลย", "ตี้หั้นเปิ้นหันลูกสาวพญายักษ์ จื่อมุกขะวดี ตึงสองฮักกั๋นเลย", "There he saw the king's daughter, Mukhawadi, and they loved each other at once."],
  H055: ["พญายักษ์เข้ามา ร้องอู้ว่าจะกิ๋นเปิ้น", "พญายักษ์เข้ามา ร้องอู้ว่าจะกิ๋นเปิ้น", "The giant king came in roaring that he would eat him."],
  H056: ["แต่ละอ่อนอู้เย็นเย็น บอกว่าตั๋วเป๋นไผ พญายักษ์เลยยกลูกสาวหื้อ", "แต่ละอ่อนอู้เย็นเย็น บอกว่าตั๋วเป๋นไผ พญายักษ์เลยยกลูกสาวหื้อ", "But the boy spoke calmly and told him who he was, and the giant gave him his daughter."],
  H057: ["แล้วกิ๋นเลี้ยงกั๋น ตึงจิ๊นปิ้งละก่อจิ๊นดิบ", "แล้วกิ๋นเลี้ยงกั๋น ตึงจิ๊นปิ้งละก่อจิ๊นดิบ", "They feasted on roast meat and raw."],
  H058: ["ตี้เมืองตี้สอง พญากุมภัณฑ์ยกลูกสาวจื่อจุละกั๋นธาหื้อ นางผิวเขียวอ่อน ต๋าดำเหมือนแก้วนิล", "ตี้เมืองตี้สอง พญากุมภัณฑ์ยกลูกสาวจื่อจุละกั๋นธาหื้อ นางผิวเขียวอ่อน ต๋าดำเหมือนแก้วนิล", "In the second city, King Kumbhanda gave him his daughter Culakantha, pale green, with eyes as black as gems."],
  H059: ["ตี้เมืองตี้สาม พญาอานุมาใจ๋ฮ้ายขนาด จ๋นหันฮอยจักรตี้ฝ่าตี๋นของละอ่อน", "ตี้เมืองตี้สาม พญาอานุมาใจ๋ฮ้ายขนาด จ๋นหันฮอยจักรตี้ฝ่าตี๋นของละอ่อน", "In the third, King Anumat came at him in a rage, until he saw the wheel on the soles of the boy's feet."],
  H060: ["พญายักษ์เลยก้มกราบ แล้วยกลูกสาวจื่อสะหลีจั๋นตาหื้อ", "พญายักษ์เลยก้มกราบ แล้วยกลูกสาวจื่อสะหลีจั๋นตาหื้อ", "Then the giant bowed down, and gave him his daughter Salicanta."],
  H061: ["แล้วบอกตางไปตางใต้ ไปเมืองยักษ์ผีดิบ", "แล้วบอกตางไปตางใต้ ไปเมืองยักษ์ผีดิบ", "And he showed him the way south, to the city of the ghouls."],
  H062: ["เปิ้นลงมาก๋างตูบในดงป่าไม้เลิ๊ก ต๋อนตี้ยักษ์ผีดิบออกไปล่าสัตว์", "เปิ้นลงมาก๋างตูบในดงป่าไม้เลิ๊ก ต๋อนตี้ยักษ์ผีดิบออกไปล่าสัตว์", "He came down among huts in the deep forest, while the ghouls were out hunting."],
  H063: ["มีแม่อุ้ยผอมขนาดนั่งอยู่คนเดียว นางคือย่าของเปิ้น", "มีแม่อุ้ยผอมขนาดนั่งอยู่คนเดียว นางคือย่าของเปิ้น", "One old woman sat there alone, thin and starving. She was his grandmother."],
  H064: ["ซาวปี๋ บ่ามีเกลือ บ่ามีไฟ บ่ามีข้าว นางเล่า ส่วนหมู่มันกิ๋นจิ๊นดิบดิบ", "ซาวปี๋ บ่ามีเกลือ บ่ามีไฟ บ่ามีข้าว นางเล่า ส่วนหมู่มันกิ๋นจิ๊นดิบดิบ", "Twenty years without salt, without fire, without rice, she said, while they eat their meat raw."],
  H065: ["เปิ้นตุบตูบละก่อหม้อน้ำของหมู่มันแตก เอาย่าขึ้นหลังหงส์ แล้วบินขึ้น", "เปิ้นตุบตูบละก่อหม้อน้ำของหมู่มันแตก เอาย่าขึ้นหลังหงส์ แล้วบินขึ้น", "He smashed their huts and their water pots, set her on the swan, and rose into the air."],
  H066: ["ยักษ์ผีดิบปิ๊กมา บินโตยไป ขว้างก้อนหินละก่อต้นไม้ใส่", "ยักษ์ผีดิบปิ๊กมา บินโตยไป ขว้างก้อนหินละก่อต้นไม้ใส่", "The ghouls came home and flew after him, throwing stones and trees."],
  H067: ["เปิ้นฟาดดาบกัญไจย หมู่ยักษ์ร่วงลุ๊กฟ้าเหมือนฝนต๊ก", "เปิ้นฟาดดาบกัญไจย หมู่ยักษ์ร่วงลุ๊กฟ้าเหมือนฝนต๊ก", "He swept Kanchai through them, and they fell from the sky like rain."],
  H068: ["ตี้จ่องดอยสูง มีเหมะราช ฮูปฮ่างคล้ายสิงห์ แต่มีปี๊ก ตั๋วหลวงเท่าจ๊าง", "ตี้จ่องดอยสูง มีเหมะราช ฮูปฮ่างคล้ายสิงห์ แต่มีปี๊ก ตั๋วหลวงเท่าจ๊าง", "In a high mountain pass lived the Hemmarat, like a lion but with wings, as big as an elephant."],
  H069: ["กู๊วันมันกืนจ๊างพลายตึงตั๋ว", "กู๊วันมันกืนจ๊างพลายตึงตั๋ว", "Every day it swallowed a bull elephant whole."],
  H070: ["มันหันหงส์ ก่อโผเข้าใส่ ดาบกัญไจยวาบเดียว สัตว์ฮ้ายก่อต๊กลงไปในป่า", "มันหันหงส์ ก่อโผเข้าใส่ ดาบกัญไจยวาบเดียว สัตว์ฮ้ายก่อต๊กลงไปในป่า", "It saw the swan, and sprang at it. With one flash of Kanchai, the beast fell into the forest."],
  H071: ["ระหว่างตางปิ๊ก ปราสาทของเมียตึงสามลอยขึ้นฟ้า บินโตยหงส์มา", "ระหว่างตางปิ๊ก ปราสาทของเมียตึงสามลอยขึ้นฟ้า บินโตยหงส์มา", "On his way home, his three wives' palaces rose into the air and followed the swan."],
  H072: ["ตี้แม่น้ำ เปิ้นหื้อตึงสามละอยู่ฝั่งพู้น แล้วปาย่าข้ามมาคนเดียว", "ตี้แม่น้ำ เปิ้นหื้อตึงสามละอยู่ฝั่งพู้น แล้วปาย่าข้ามมาคนเดียว", "At the river he left them on the far bank, and took his grandmother across alone."],
  H073: ["ปี้น้องตึงหกละอยู่ หมู่เขาแย่งเอาย่าไป รุมกั๋นตี๋ละอ่อนจ๋นต๋าย", "ปี้น้องตึงหกละอยู่ หมู่เขาแย่งเอาย่าไป รุมกั๋นตี๋ละอ่อนจ๋นต๋าย", "The six brothers were waiting. They took the old woman, fell on him all together, and killed him."],
  H074: ["ขว้างเปิ้นไว้ในป่าหญ้า เอาย่าขึ้นหลังจ๊าง แล้วฟ้าวปิ๊กไปฮับรางวัล", "ขว้างเปิ้นไว้ในป่าหญ้า เอาย่าขึ้นหลังจ๊าง แล้วฟ้าวปิ๊กไปฮับรางวัล", "They left him in the weeds, put her on an elephant, and rode through the night to claim the reward."],
  H097: ["หมู่เขาบอกย่าว่า เปิ้นแค่สลบไป ย่าจะได้บ่าฮ้องไห้", "หมู่เขาบอกย่าว่า เปิ้นแค่สลบไป ย่าจะได้บ่าฮ้องไห้", "They told the old woman he was only knocked out, so that she would not cry out."],
  H075: ["เมื่อเปิ้นบ่าปิ๊กมา ลูกสาวพญายักษ์ตึงสามข้ามน้ำมา แล้วก่อหันเปิ้น", "เมื่อเปิ้นบ่าปิ๊กมา ลูกสาวพญายักษ์ตึงสามข้ามน้ำมา แล้วก่อหันเปิ้น", "When he did not come back, the three princesses crossed the river and found him."],
  H076: ["พระอินทร์ลงมาลอง แปลงเป๋นเจ้าจายฮูปงาม เอาปราสาทมาหื้อ นางตึงสามบ่ายอม ฮักก้าผัวของตั๋ว", "พระอินทร์ลงมาลอง แปลงเป๋นเจ้าจายฮูปงาม เอาปราสาทมาหื้อ นางตึงสามบ่ายอม ฮักก้าผัวของตั๋ว", "Indra came down to test them, as a handsome prince, offering them palaces. They would have no one but their husband."],
  H077: ["แล้วแปลงเป๋นยักษ์ฮ้าย จะกิ๋นร่างของเปิ้น นางตึงสามว่า จะก่อไฟกองหลวง แล้วโดดเข้าไป ต๋ายไปตวยเปิ้น", "แล้วแปลงเป๋นยักษ์ฮ้าย จะกิ๋นร่างของเปิ้น นางตึงสามว่า จะก่อไฟกองหลวง แล้วโดดเข้าไป ต๋ายไปตวยเปิ้น", "Then as a monster, who would eat the body. They said they would build a fire and leap into it, to die with him."],
  H078: ["แล้วพระอินทร์แปลงเป๋นพราหมณ์เฒ่า เทยาทิพย์ลงบนแผล ละอ่อนก่อฟื้นคืนมา", "แล้วพระอินทร์แปลงเป๋นพราหมณ์เฒ่า เทยาทิพย์ลงบนแผล ละอ่อนก่อฟื้นคืนมา", "Then Indra came as an old Brahman, poured heavenly medicine on the boy's wounds, and he lived again."],
  H098: ["ละอ่อนเลยใค่ไปเมือง ไปซอกหาพระญากับแม่ของเปิ้น", "ละอ่อนเลยใค่ไปเมือง ไปซอกหาพระญากับแม่ของเปิ้น", "He decided to go to the city, to find the king and his mother."],
  H079: ["ตี้ปาราณสี ปี้น้องตึงหกเป๋นคนเก่งแห๋ม พระญาเตียมงานเลี้ยงหลวง", "ตี้ปาราณสี ปี้น้องตึงหกเป๋นคนเก่งแห๋ม พระญาเตียมงานเลี้ยงหลวง", "In Varanasi the brothers were heroes again, and the king made ready a great feast."],
  H080: ["แต่แม่ของพระญาไห้กู๊วัน เปิ้นว่า บ่าแม่นหกคนนั้นตี้จ่วยข้า", "แต่แม่ของพระญาไห้กู๊วัน เปิ้นว่า บ่าแม่นหกคนนั้นตี้จ่วยข้า", "But his mother wept every day. Those six never saved me, she said."],
  H081: ["ละอ่อนขี่หงส์หินปาข้าออกมา หมู่มันก้าแย่งข้าไปตี้แม่น้ำ", "ละอ่อนขี่หงส์หินปาข้าออกมา หมู่มันก้าแย่งข้าไปตี้แม่น้ำ", "A shining boy on a swan of stone brought me out. They only took me from him at the river."],
  H099: ["พระญาใค่ซอกหาคนตี้ขี่หงส์ โดยบ่าหื้อปี้น้องตึงหกฮู้", "พระญาใค่ซอกหาคนตี้ขี่หงส์ โดยบ่าหื้อปี้น้องตึงหกฮู้", "The king wanted to look for the one on the swan, without the brothers knowing."],
  H082: ["พระญาเลยแป๋งพลับพลาสูงตี้ข่วงงาน หื้อคนตึงเมืองเข้าตางประตู๋เดียว", "พระญาเลยแป๋งพลับพลาสูงตี้ข่วงงาน หื้อคนตึงเมืองเข้าตางประตู๋เดียว", "So the king built a high pavilion at the fair, and the whole city had to come in by one gate."],
  H083: ["เมื่อละอ่อนเตียวเข้ามา ย่าหันเปิ้น ก่อฮ้องหาหลาน", "เมื่อละอ่อนเตียวเข้ามา ย่าหันเปิ้น ก่อฮ้องหาหลาน", "When the boy came through, his grandmother saw him and called out to her grandson."],
  H084: ["ต่อหน้าบัลลังก์ ละอ่อนเล่ากู๊อย่าง ลูกหมา คำ ย่ายักษ์ ยักษ์ผีดิบ ละก่อแม่น้ำ", "ต่อหน้าบัลลังก์ ละอ่อนเล่ากู๊อย่าง ลูกหมา คำ ย่ายักษ์ ยักษ์ผีดิบ ละก่อแม่น้ำ", "Before the throne, the boy told it all: the puppy, the gold, the giantess, the ghouls, and the river."],
  H085: ["เมียน้อยตึงหกว่าจุ๊ จ๋นนางข้าหลวงมา นางเป๋นเจ้าของลูกหมาลายตี้ถูกเอาไปคืนนั้น", "เมียน้อยตึงหกว่าจุ๊ จ๋นนางข้าหลวงมา นางเป๋นเจ้าของลูกหมาลายตี้ถูกเอาไปคืนนั้น", "The six wives said it was a lie, until the palace maid came, whose spotted puppy they had taken that night."],
  H086: ["เมื่อถูกใส่ขื่อคา เมียน้อยตึงหกกับลูกจายก่อยอมฮับ", "เมื่อถูกใส่ขื่อคา เมียน้อยตึงหกกับลูกจายก่อยอมฮับ", "In fetters, the six wives and their sons told the truth."],
  H087: ["แล้วหมู่เขาก่อถูกลงโทษหนักขนาด", "แล้วหมู่เขาก่อถูกลงโทษหนักขนาด", "And they were punished severely."],
  H088: ["พระญาส่งขุนนางไปฮับนางวิมาลา นางไล่ปิ๊กไป", "พระญาส่งขุนนางไปฮับนางวิมาลา นางไล่ปิ๊กไป", "The king sent his ministers for Vimala. She sent them away."],
  H089: ["ถ้วยตี้แตกแล้วต่อบ่าได้ นางว่า ข้าจะอยู่ตี้นี่กับลูก", "ถ้วยตี้แตกแล้วต่อบ่าได้ นางว่า ข้าจะอยู่ตี้นี่กับลูก", "A broken bowl cannot be mended, she said. I will stay here with my son."],
  H090: ["แล้วพระญามาเอง คุกเข่าในสวน ไห้ ขอหื้อนางอภัยหื้อ", "แล้วพระญามาเอง คุกเข่าในสวน ไห้ ขอหื้อนางอภัยหื้อ", "Then the king came himself, knelt in the garden, and wept, and begged her to forgive him."],
  H091: ["นางอภัยหื้อ ละก่อขอเพียงอย่างเดียว หื้อป้ออุ้ยแม่อุ้ยคนสวนไปตวย", "นางอภัยหื้อ ละก่อขอเพียงอย่างเดียว หื้อป้ออุ้ยแม่อุ้ยคนสวนไปตวย", "She forgave him. And she asked one thing: that the old gardeners come with her."],
  H092: ["ลูกสาวพญายักษ์ตึงสามเอาปราสาทลงมาในกำแปงหอคำ", "ลูกสาวพญายักษ์ตึงสามเอาปราสาทลงมาในกำแปงหอคำ", "The three princesses brought their palaces down inside the palace walls."],
  H093: ["เจ็ดวันเจ็ดคืน คนตึงเมืองฟ้อนกั๋นม่วนขนาด", "เจ็ดวันเจ็ดคืน คนตึงเมืองฟ้อนกั๋นม่วนขนาด", "For seven days and seven nights the city danced."],
  H094: ["เขาฮดน้ำลุ๊กหอยสังข์ ละก่อเฮียกขวัญด้วยขันบายศรี", "เขาฮดน้ำลุ๊กหอยสังข์ ละก่อเฮียกขวัญด้วยขันบายศรี", "They poured water over him from conch shells, and called his spirits home with the bai si."],
  H095: ["ละก่อเจ้าจายตี้เกิ๊ดมาลุ๊กความตุ๊ก ได้เป๋นพระญาเมืองปาราณสี", "ละก่อเจ้าจายตี้เกิ๊ดมาลุ๊กความตุ๊ก ได้เป๋นพระญาเมืองปาราณสี", "And the boy born of suffering became king of Varanasi."],
  H096: ["เปิ้นครองเมือง มีแม่อยู่ข้างข้าง ด้วยความเมตต๋าละก่อความยุติธรรม ละก่อหงส์หินก่อเฝ้าอยู่บนหลังคา", "เปิ้นครองเมือง มีแม่อยู่ข้างข้าง ด้วยความเมตต๋าละก่อความยุติธรรม ละก่อหงส์หินก่อเฝ้าอยู่บนหลังคา", "He ruled with his mother beside him, kindly and justly, and the stone swan kept watch from the roof."],
};
